import { Group, Mesh, PlaneGeometry, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, uniform, float, texture, add, sub, mul } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();

  // ----- Scene-unit sizing (hub frame at fov50, z=10) -----
  const W = 3.2;
  const H = 2.0; // matches atlas region aspect 512:320 = 1.6:1

  // ----- Backdrop gradient plane (engineered surface) -----
  const backdropGeo = new THREE.PlaneGeometry(W * 1.6, H * 1.6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.transparent = true;
  backdropMat.opacityNode = float(1.0);

  const cSurface = uniform(new THREE.Color('#0b0b10'));
  const cInk = uniform(new THREE.Color('#16161d'));

  const bu = uv().x;
  const bv = uv().y;
  // Diagonal engineered gradient: surface top-left -> ink bottom-right
  const diag = smoothstep(float(0.0), float(1.0), bu.add(bv).mul(float(0.5)));
  const backColor = mix(cSurface, cInk, diag);
  // Soft vignette to keep edges darker than the card
  const cx = bu.sub(float(0.5)).mul(float(2.0));
  const cy = bv.sub(float(0.5)).mul(float(2.0));
  const vig = float(1.0).sub(cx.powNumber(2.0).add(cy.powNumber(2.0)).mul(float(0.45)));
  backdropMat.colorNode = backColor.mul(vig);

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -0.6);
  group.add(backdrop);

  // ----- Primary card plane (ceramic grain + engineered gradient) -----
  const cardGeo = new THREE.PlaneGeometry(W, H);
  const cardMat = new MeshBasicNodeMaterial();
  cardMat.transparent = true;

  const cAccent = uniform(new THREE.Color('#ff2a38'));
  const cPaper = uniform(new THREE.Color('#e8ecf2'));

  // Color vars default until texture resolves
  let grainTex = null;

  const v = uv().y;
  const u = uv().x;

  // Engineered vertical gradient: ink at top -> slightly warmer surface at bottom
  const grad = smoothstep(float(0.0), float(1.0), v);
  const baseGrad = mix(cInk.mul(float(0.55)), cInk, grad);

  // Subtle ceramic grain overlay (uses loaded map, low contribution)
  const grainNode = texture(grainTex !== null ? grainTex : null, uv());
  // Default when texture is null: TSL falls back to black sample; guard with uniform flag
  const grainReady = uniform(0);
  const grainSample = grainNode.r.sub(float(0.5)).mul(float(0.05));
  const grainOverlay = grainSample.mul(grainReady);
  const withGrain = baseGrad.add(vec3(grainOverlay, grainOverlay, grainOverlay));

  // Thin accent rule along the top edge (<=~3% of frame width — accent discipline)
  const topAccent = smoothstep(float(0.965), float(0.985), v)
    .mul(smoothstep(float(0.995), float(0.985), v))
    .mul(u.smoothstep(float(0.05), float(0.95))); // inset horizontally
  const cardColor = mix(withGrain, cAccent, topAccent);

  // Subtle hairline frame in paper tone (engineered look)
  const frameEdge = float(0.018);
  const frameMask =
    u.smoothstep(float(0.0), float(0.02)).mul(u.smoothstep(float(1.0), float(0.98)))
      .add(v.smoothstep(float(0.0), float(0.02)).mul(v.smoothstep(float(1.0), float(0.98))))
      .clamp(0, 1);
  const finalColor = mix(cardColor, cPaper.mul(float(0.12)), frameMask.mul(float(0.18)));

  cardMat.colorNode = finalColor;
  cardMat.opacityNode = float(1.0);

  const card = new THREE.Mesh(cardGeo, cardMat);
  card.position.set(0, 0, 0);
  group.add(card);

  // Load the ceramic-grain texture asynchronously and wire into TSL
  const loaders = [];
  if (config.imageUrl) {
    loaders.push(
      ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
        tex.wrapS = THREE.RepeatWrapping;
        tex.wrapT = THREE.RepeatWrapping;
        // Pull atlas region (0,0,512,320) — total atlas assumed 512x512;
        // since the source rect starts at 0,0 and matches this logical grain tile,
        // we sample the full texture (the asset IS the relevant grain map).
        grainTex = tex;
        grainNode.value = tex; // rebind TSL texture node
        grainReady.value = 1;
        cardMat.needsUpdate = true;
      }).catch(() => { /* swallow: gradient-only fallback */ })
    );
  }

  // ----- Entrance motion (rise-in, engine-codex preset) -----
  const intro = gsap.timeline();
  group.position.y = 0.4;
  group.scale.set(0.965, 0.965, 0.965);
  intro.to(group.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  intro.to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power3.out' }, 0);
  intro.to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }, '>-0.05');

  // ----- Handlers (none interactive; reserve shape) -----
  group.userData.handlers = {
    click: () => {},
    hover: () => {},
  };

  group.userData.cleanup = () => {
    intro.kill();
    backdropGeo.dispose();
    backdropMat.dispose();
    cardGeo.dispose();
    cardMat.dispose();
    if (grainTex) grainTex.dispose();
  };

  return group;
}
